cases.bad:
const originalParent = player.parentElement;
// ... later, on exit:
originalParent.appendChild(player); // may be detached by now

cases.good:
const originalParent = player.parentElement;
const doomedAncestor = player.closest('[data-cell-split-view="stage"]');
const wrapper = doomedAncestor?.closest('[data-cell-split-view="wrapper"]');
const liveAnchorParent = wrapper?.parentElement ?? null;
// ... on exit:
const target = originalParent?.isConnected ? originalParent
  : liveAnchorParent?.isConnected ? liveAnchorParent : null;
if (target) target.appendChild(player);
